        /// </summary>
        public SemanticSection ProjectTyped<T>(SemanticDocumentSection section, ImmutableArray<T>.Builder entities, SemanticEntityProjector<T> projector)
        {
            if (section.Value.ValueKind != JsonValueKind.Array)
            {
                Report("SectionNotArray", SemanticSeverity.Error, section.Name, null, null, "A section must be a JSON array of rows; it is retained verbatim.");
                return new SemanticSection(section.Name, section.Ordinal, SemanticSectionDisposition.Typed, 0, ImmutableArray<SemanticSectionRow>.Empty, SemanticJson.From(section.Value), _unordered.Contains(section.Name));
            }

            ImmutableArray<SemanticSectionRow>.Builder rows = ImmutableArray.CreateBuilder<SemanticSectionRow>();
            int index = 0;
            foreach (JsonElement row in section.Value.EnumerateArray())
            {
                SemanticRowDisposition disposition = Classify(section.Name, row, index, out string? marker);
                if (disposition == SemanticRowDisposition.Entity && projector(this, row, index, out T entity))
                {
                    rows.Add(new SemanticSectionRow(index, SemanticRowDisposition.Entity, entities.Count, null, null));
                    entities.Add(entity);
                }
                else
                {
                    SemanticRowDisposition retained = disposition == SemanticRowDisposition.Entity ? SemanticRowDisposition.Unprojected : disposition;
                    rows.Add(new SemanticSectionRow(index, retained, null, marker, SemanticJson.From(row)));
                }

                index++;
            }

            return new SemanticSection(section.Name, section.Ordinal, SemanticSectionDisposition.Typed, index, rows.ToImmutable(), null, _unordered.Contains(section.Name));
        }

