                {
                    Report("DuplicateProperty", SemanticSeverity.Error, section, index, property.Name, "The row declares this property more than once.");
                    return false;
                }
            }

            bool conforms = true;
            if (row.TryGetProperty(Convention.LabelField, out JsonElement label) == false)
            {
                Report("FieldAbsent", SemanticSeverity.Error, section, index, Convention.LabelField, "The row has no section label.");
                conforms = false;
            }
            else if (label.ValueKind != JsonValueKind.String || string.Equals(label.GetString(), section, StringComparison.Ordinal) == false)
            {
                Report("LabelMismatch", SemanticSeverity.Error, section, index, Convention.LabelField, "The row's section label does not name the section that contains it.");
                conforms = false;
            }

            if (Convention.ScopeField is { } scopeField)
            {
                if (row.TryGetProperty(scopeField, out JsonElement scope) == false)
                {
                    Report("FieldAbsent", SemanticSeverity.Error, section, index, scopeField, "The row has no scope identity.");
                    conforms = false;
                }
                else if (scope.ValueKind != JsonValueKind.String || string.Equals(scope.GetString(), Identity, StringComparison.Ordinal) == false)
                {
                    Report("ScopeMismatch", SemanticSeverity.Error, section, index, scopeField, "The row's scope identity is not the requested identity (ordinal comparison).");
                    conforms = false;
                }
            }

            if (requireDiscriminator && Convention.DiscriminatorField is { } discriminatorField)
            {
                if (row.TryGetProperty(discriminatorField, out JsonElement discriminator) == false)
                {
                    Report("FieldAbsent", SemanticSeverity.Error, section, index, discriminatorField, "The row has no discriminator.");
                    conforms = false;
                }
                else if (discriminator.ValueKind != JsonValueKind.String)
                {
                    Report("FieldType", SemanticSeverity.Error, section, index, discriminatorField, "The row's discriminator must be a string.");
                    conforms = false;
                }
            }

            return conforms;
        }

        public bool TryReadString(JsonElement row, string section, int index, string field, bool nullable, out string? value)
        {
            value = null;
            if (TryGetValue(row, section, index, field, nullable, out JsonElement element) == false)
            {
                return false;
            }

            if (element.ValueKind == JsonValueKind.Null)
            {
                return true;
            }

            if (element.ValueKind != JsonValueKind.String)
            {
                return TypeMismatch(section, index, field, "string");
            }

            try
            {
                value = element.GetString();
            }
            catch (InvalidOperationException)
            {
                Report("FieldNotRepresentable", SemanticSeverity.Error, section, index, field, "The string is not valid UTF-16 text; the row is retained verbatim.");
                return false;
            }

            return true;
        }

        public bool TryReadInt64(JsonElement row, string section, int index, string field, bool nullable, out long? value)
        {
            value = null;
            if (TryGetValue(row, section, index, field, nullable, out JsonElement element) == false)
            {
                return false;
            }

            if (element.ValueKind == JsonValueKind.Null)
            {
                return true;
            }

            if (element.ValueKind != JsonValueKind.Number || element.TryGetInt64(out long parsed) == false)
            {
                return TypeMismatch(section, index, field, "int64");
            }

            if (string.Equals(parsed.ToString(CultureInfo.InvariantCulture), element.GetRawText(), StringComparison.Ordinal) == false)
            {
                Report("FieldNotCanonical", SemanticSeverity.Error, section, index, field, "The integer's source spelling cannot be reproduced exactly; the row is retained verbatim.");
                return false;
            }

            value = parsed;
            return true;
        }

        public bool TryReadInt32(JsonElement row, string section, int index, string field, bool nullable, out int? value)
        {
            value = null;
            if (TryReadInt64(row, section, index, field, nullable, out long? wide) == false)
            {
                return false;
            }

            if (wide == null)
            {
                return true;
            }

            if (wide.Value < int.MinValue || wide.Value > int.MaxValue)
            {
                return TypeMismatch(section, index, field, "int32");
            }

            value = (int)wide.Value;
            return true;
        }

        public bool TryReadBoolean(JsonElement row, string section, int index, string field, bool nullable, out bool? value)
        {
            value = null;
            if (TryGetValue(row, section, index, field, nullable, out JsonElement element) == false)
            {
                return false;
            }

            switch (element.ValueKind)
            {
                case JsonValueKind.Null:
                    return true;
                case JsonValueKind.True:
                    value = true;
                    return true;
                case JsonValueKind.False:
                    value = false;
                    return true;
                default:
                    return TypeMismatch(section, index, field, "boolean");
            }
        }

        public bool TryReadJson(JsonElement row, string section, int index, string field, bool nullable, out SemanticJson? value)
        {
            value = null;
            if (TryGetValue(row, section, index, field, nullable, out JsonElement element) == false)
            {
                return false;
            }

            if (element.ValueKind != JsonValueKind.Null)
            {
                value = SemanticJson.From(element);
            }

            return true;
        }

        /// <summary>Retains every row property the contract does not declare, reporting each new one once per section.</summary>
        public ImmutableArray<SemanticField> Unmapped(JsonElement row, string section, ISet<string> known)
        {
            ImmutableArray<SemanticField>.Builder? builder = null;
            foreach (JsonProperty property in row.EnumerateObject())
            {
                if (known.Contains(property.Name))
                {
                    continue;
                }

                builder ??= ImmutableArray.CreateBuilder<SemanticField>();
                builder.Add(new SemanticField(property.Name, SemanticJson.From(property.Value)));
                if (_reportedUnmapped.Add(section + "\u0000" + property.Name))
                {
                    Report("UnmappedField", SemanticSeverity.Info, section, null, property.Name, "The contract does not declare this field; its value is retained verbatim on each row.");
                }
            }

            return builder == null ? ImmutableArray<SemanticField>.Empty : builder.ToImmutable();
        }

        private bool TryGetValue(JsonElement row, string section, int index, string field, bool nullable, out JsonElement element)
        {
            if (row.TryGetProperty(field, out element) == false)
            {
                Report("FieldAbsent", SemanticSeverity.Error, section, index, field, "The declared field is absent; this source writes nulls explicitly, so absence is a contract mismatch.");
                return false;
            }

            if (element.ValueKind == JsonValueKind.Null && nullable == false)
            {
                Report("FieldNull", SemanticSeverity.Error, section, index, field, "The declared field is required but the source value is null.");
                return false;
            }

            return true;
        }

        private bool TypeMismatch(string section, int index, string field, string declaredType)
        {
            Report("FieldType", SemanticSeverity.Error, section, index, field, "The source value does not have the declared type '" + declaredType + "'.");
            return false;
        }
    }

    /// <summary>
    /// A JSON object whose members are written in RFC 8785 order (UTF-16 code units). Members
    /// are strings, booleans, null, nested objects or lists; JSON numbers are refused so exact
    /// integers travel as declared decimal strings.
    /// </summary>
    public sealed class SemanticCanonicalObject
    {
        private readonly SortedDictionary<string, object?> _members = new SortedDictionary<string, object?>(StringComparer.Ordinal);

        public SemanticCanonicalObject Add(string name, object? value)
        {
            if (_members.ContainsKey(name))
            {
                throw new InvalidOperationException("Duplicate canonical member '" + name + "'.");
            }

            _members.Add(name, value);
            return this;
        }

        internal IEnumerable<KeyValuePair<string, object?>> Members => _members;
    }

    /// <summary>
    /// The projection payload serializer: RFC 8785 member ordering and string escaping over a
    /// value domain without JSON numbers. Opaque source fragments are bound by the SHA-256 of
    /// their exact source text.
    /// </summary>
    public static class SemanticCanonicalJson
    {
        /// <summary>Identifies this canonical form in digests and receipts.</summary>
        public const string Algorithm = "sha256:rfc8785-ordering;numbers-as-declared-strings;opaque-as-source-sha256";

        public static string Serialize(object? value)
        {
            var builder = new StringBuilder();
            Write(builder, value);
            return builder.ToString();
        }

        public static string Sha256Hex(string text)
        {
            return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text))).ToLowerInvariant();
        }

        public static object? Int64(long? value) => value?.ToString(CultureInfo.InvariantCulture);

        public static object? Int32(int? value) => value?.ToString(CultureInfo.InvariantCulture);

        public static object? Boolean(bool? value) => value;

        public static object? Opaque(SemanticJson? value)
        {
            if (value is not { } json)
            {
                return null;
            }

            return new SemanticCanonicalObject().Add("kind", json.Kind.ToString()).Add("sha256", json.Sha256());
        }

        public static object? Fields(ImmutableArray<SemanticField> fields)
        {
            if (fields.IsDefaultOrEmpty)
            {
                return null;
            }

            var result = new SemanticCanonicalObject();
            foreach (SemanticField field in fields)
            {
                result.Add(field.Name, Opaque(field.Value));
            }

            return result;
        }

        private static void Write(StringBuilder builder, object? value)
        {
            switch (value)
            {
                case null:
                    builder.Append("null");
                    break;
                case bool boolean:
                    builder.Append(boolean ? "true" : "false");
                    break;
                case string text:
                    WriteString(builder, text);
                    break;
                case SemanticCanonicalObject canonicalObject:
                    builder.Append('{');
                    bool first = true;
                    foreach (KeyValuePair<string, object?> member in canonicalObject.Members)
                    {
                        if (first == false)
                        {
                            builder.Append(',');
                        }

                        first = false;
                        WriteString(builder, member.Key);
                        builder.Append(':');
                        Write(builder, member.Value);
                    }

                    builder.Append('}');
                    break;
                case System.Collections.IEnumerable list:
                    builder.Append('[');
                    bool firstItem = true;
                    foreach (object? item in list)
                    {
                        if (firstItem == false)
                        {
                            builder.Append(',');
                        }

                        firstItem = false;
                        Write(builder, item);
                    }

                    builder.Append(']');
                    break;
                default:
                    throw new InvalidOperationException("Canonical payloads carry no JSON numbers or '" + value.GetType().Name + "' values; encode them as declared strings.");
            }
        }

        private static void WriteString(StringBuilder builder, string text)
        {
            builder.Append('"');
            for (int index = 0; index < text.Length; index++)
            {
                char character = text[index];
                switch (character)
                {
                    case '"':
                        builder.Append("\\\"");
                        continue;
                    case '\\':
                        builder.Append("\\\\");
                        continue;
                    case '\b':
                        builder.Append("\\b");
                        continue;
                    case '\f':
                        builder.Append("\\f");
                        continue;
                    case '\n':
                        builder.Append("\\n");
                        continue;
                    case '\r':
                        builder.Append("\\r");
                        continue;
                    case '\t':
                        builder.Append("\\t");
                        continue;
                }

                if (character < 0x20)
                {
                    builder.Append("\\u").Append(((int)character).ToString("x4", CultureInfo.InvariantCulture));
                }
                else if (char.IsHighSurrogate(character))
                {
                    if (index + 1 >= text.Length || char.IsLowSurrogate(text[index + 1]) == false)
                    {
                        throw new InvalidOperationException("A canonical string contains an unpaired surrogate.");
                    }

                    builder.Append(character).Append(text[index + 1]);
                    index++;
                }
                else if (char.IsLowSurrogate(character))
                {
                    throw new InvalidOperationException("A canonical string contains an unpaired surrogate.");
                }
                else
                {
                    builder.Append(character);
                }
            }

            builder.Append('"');
        }
    }

    /// <summary>Builds the contract-independent parts of a projection payload.</summary>
    internal static class SemanticPayload
    {
        public static object Arguments(ImmutableArray<SemanticBoundArgument> arguments)
        {
            var list = new List<object?>();
            foreach (SemanticBoundArgument argument in arguments)
            {
                list.Add(new SemanticCanonicalObject()
                    .Add("parameter", argument.Parameter)
                    .Add("sqlType", argument.SqlType)
                    .Add("binding", argument.Binding.ToString())
                    .Add("role", argument.Role)
                    .Add("value", argument.Value));
            }

            return list;
        }

        public static object? Refusal(SemanticSourceRefusal? refusal)
        {
            if (refusal == null)
            {
                return null;
            }

            return new SemanticCanonicalObject()
                .Add("errorNumber", refusal.ErrorNumber.ToString(CultureInfo.InvariantCulture))
                .Add("code", refusal.Code)
                .Add("availability", refusal.Availability.ToString());
        }

        public static object ResultSets(ImmutableArray<SemanticResultSetShape> resultSets)
        {
            var list = new List<object?>();
            foreach (SemanticResultSetShape shape in resultSets)
            {
                var columns = new List<object?>();
                foreach (SemanticColumn column in shape.Columns)
                {
                    columns.Add(new SemanticCanonicalObject()
                        .Add("name", column.Name)
                        .Add("sqlType", column.SqlType)
                        .Add("allowsNull", column.AllowsNull)
                    .Add("withheld", column.Withheld));
                }

                list.Add(new SemanticCanonicalObject()
                    .Add("ordinal", shape.Ordinal.ToString(CultureInfo.InvariantCulture))
                    .Add("section", shape.Section)
                    .Add("rowCount", shape.RowCount.ToString(CultureInfo.InvariantCulture))
                    .Add("withheldValues", shape.WithheldValues.ToString(CultureInfo.InvariantCulture))
                    .Add("columns", columns));
            }

            return list;
        }

        public static object Dependencies(IEnumerable<SemanticDependency> dependencies)
        {
            var list = new List<object?>();
            foreach (SemanticDependency dependency in dependencies)
            {
                list.Add(new SemanticCanonicalObject()
                    .Add("source", dependency.Source)
                    .Add("kind", dependency.Kind)
                    .Add("id", dependency.Id)
                    .Add("locator", dependency.Locator)
                    .Add("digest", dependency.Digest));
            }

            return list;
        }

        /// <summary>
        /// A section's payload. An order-free section is a sorted multiset: row indexes are omitted and
        /// rows (or, for a retained section, row source-text digests) are sorted, so source row order
        /// cannot change the digest while row content still does.
        /// </summary>
        public static object Section(SemanticSection section, Func<SemanticSectionRow, object?> entity)
        {
            var result = new SemanticCanonicalObject()
                .Add("name", section.Name)
                .Add("ordinal", section.Ordinal.ToString(CultureInfo.InvariantCulture))
                .Add("disposition", section.Disposition.ToString())
                .Add("rowCount", section.RowCount.ToString(CultureInfo.InvariantCulture))
                .Add("unordered", section.Unordered);
            if (section.Raw is { } raw)
            {
                result.Add("raw", section.Unordered && raw.Kind == JsonValueKind.Array ? RowMultiset(raw) : SemanticCanonicalJson.Opaque(raw));
                return result.Add("rows", null);
            }

            result.Add("raw", null);
            var rows = new List<object?>();
            foreach (SemanticSectionRow row in section.Rows)
            {
                var item = new SemanticCanonicalObject()
                    .Add("disposition", row.Disposition.ToString());
                if (section.Unordered == false)
                {
                    item.Add("index", row.Index.ToString(CultureInfo.InvariantCulture));
                }

                switch (row.Disposition)
                {
                    case SemanticRowDisposition.Entity:
                        item.Add("entity", entity(row));
                        break;
                    case SemanticRowDisposition.Marker:
                        item.Add("marker", row.Marker).Add("source", SemanticCanonicalJson.Opaque(row.Raw));
                        break;
                    default:
                        item.Add("source", SemanticCanonicalJson.Opaque(row.Raw));
                        break;
                }

                rows.Add(item);
            }

            return result.Add("rows", section.Unordered ? Sorted(rows) : rows);
        }

        /// <summary>
        /// Diagnostics without messages, sorted. A diagnostic located in an order-free section loses its
        /// row index, which is an artifact of source row order there.
        /// </summary>
        public static object Diagnostics(ImmutableArray<SemanticDiagnostic> diagnostics, ImmutableArray<SemanticSection> sections)
        {
            var unordered = new HashSet<string>(sections.Where(section => section.Unordered).Select(section => section.Name), StringComparer.Ordinal);
            var list = new List<object?>();
            foreach (SemanticDiagnostic diagnostic in diagnostics)
            {
                bool located = diagnostic.Section == null || unordered.Contains(diagnostic.Section) == false;
                list.Add(new SemanticCanonicalObject()
                    .Add("code", diagnostic.Code)
                    .Add("severity", diagnostic.Severity.ToString())
                    .Add("section", diagnostic.Section)
                    .Add("row", located ? diagnostic.Row?.ToString(CultureInfo.InvariantCulture) : null)
                    .Add("field", diagnostic.Field));
            }

            return Sorted(list);
        }

        private static List<object?> Sorted(List<object?> items) =>
            items.Select(item => (Item: item, Text: SemanticCanonicalJson.Serialize(item))).OrderBy(pair => pair.Text, StringComparer.Ordinal).Select(pair => pair.Item).ToList();

        private static object RowMultiset(SemanticJson raw)
        {
            using JsonDocument document = JsonDocument.Parse(raw.RawText, new JsonDocumentOptions { MaxDepth = 256 });
            List<object?> rows = document.RootElement.EnumerateArray()
                .Select(row => SemanticCanonicalJson.Sha256Hex(row.GetRawText()))
                .OrderBy(digest => digest, StringComparer.Ordinal)
                .Cast<object?>()
                .ToList();
            return new SemanticCanonicalObject().Add("kind", "ArrayMultiset").Add("rowSha256", rows);
        }
    }

    /// <summary>Writes the contract-independent parts of an inspection view and the source form of typed values.</summary>
    internal static class SemanticWriting
    {
        public static void Raw(Utf8JsonWriter writer, string name, SemanticJson? value)
        {
            writer.WritePropertyName(name);
            if (value is { } json)
            {
                writer.WriteRawValue(json.RawText, skipInputValidation: true);
            }
            else
            {
                writer.WriteNullValue();
            }
        }

        public static void Opaque(Utf8JsonWriter writer, string name, SemanticJson? value)
        {
            if (value is not { } json)
            {
                writer.WriteNull(name);
                return;
            }

            writer.WriteStartObject(name);
            writer.WriteString("kind", json.Kind.ToString());
            writer.WriteNumber("utf8Bytes", Encoding.UTF8.GetByteCount(json.RawText));
            writer.WriteString("sha256", json.Sha256());
            writer.WriteEndObject();
        }

        public static void Identity(Utf8JsonWriter writer, SemanticIdentity? identity)
        {
            if (identity == null)
            {
                writer.WriteNull("identity");
                return;
            }

            writer.WriteStartObject("identity");
            writer.WriteString("namespace", identity.Namespace);
            writer.WriteString("kind", identity.Kind);
            writer.WriteString("declaredId", identity.DeclaredId);
            writer.WriteString("revision", identity.Revision);
            writer.WriteString("revisionScope", "source-database locator; not a portable content revision");
            writer.WriteEndObject();
        }

        public static void Refusal(Utf8JsonWriter writer, SemanticSourceRefusal? refusal)
        {
            if (refusal == null)
            {
                writer.WriteNull("refusal");
                return;
            }

            writer.WriteStartObject("refusal");
            writer.WriteNumber("errorNumber", refusal.ErrorNumber);
            writer.WriteString("code", refusal.Code);
            writer.WriteString("availability", refusal.Availability.ToString());
            writer.WriteEndObject();
        }

        public static void Provenance(Utf8JsonWriter writer, SemanticProvenance provenance)
        {
            writer.WriteStartObject("provenance");
            writer.WriteString("procedure", provenance.Procedure);
            writer.WriteStartArray("arguments");
            foreach (SemanticBoundArgument argument in provenance.Arguments)
            {
                writer.WriteStartObject();
                writer.WriteString("parameter", argument.Parameter);
                writer.WriteString("sqlType", argument.SqlType);
                writer.WriteString("binding", argument.Binding.ToString());
                writer.WriteString("role", argument.Role);
                writer.WriteString("value", argument.Value);
                writer.WriteEndObject();
            }

            writer.WriteEndArray();
            writer.WriteNumber("rowResultSets", provenance.RowResultSets);
            writer.WriteString("documentSha256", provenance.DocumentSha256);
            if (provenance.DocumentUtf8Bytes is { } bytes)
            {
                writer.WriteNumber("documentUtf8Bytes", bytes);
            }
            else
            {
                writer.WriteNull("documentUtf8Bytes");
            }

            SemanticCapture capture = provenance.Capture;
            writer.WriteStartObject("capture");
            writer.WriteString("database", capture.Database);
            writer.WriteString("readerDefinitionDigest", capture.ReaderDefinitionDigest);
            writer.WriteString("isolation", capture.Isolation);
            writer.WriteString("transactionOutcome", capture.TransactionOutcome);
            if (capture.DatabaseLogRecords is { } records)
            {
                writer.WriteNumber("databaseLogRecords", records);
            }
            else
            {
                writer.WriteNull("databaseLogRecords");
            }

            writer.WriteString("capturedAtUtc", capture.CapturedAtUtc?.ToString("O", CultureInfo.InvariantCulture));
            if (capture.ElapsedMilliseconds is { } elapsed)
            {
                writer.WriteNumber("elapsedMilliseconds", elapsed);
            }
            else
            {
                writer.WriteNull("elapsedMilliseconds");
            }

            writer.WriteStartArray("pinnedRevisions");
            foreach (SemanticDependency dependency in capture.PinnedRevisions)
            {
                Dependency(writer, dependency);
            }

            writer.WriteEndArray();
            writer.WriteEndObject();
            writer.WriteEndObject();
        }

        public static void ResultSets(Utf8JsonWriter writer, ImmutableArray<SemanticResultSetShape> resultSets)
        {
            writer.WriteStartArray("resultSets");
            foreach (SemanticResultSetShape shape in resultSets)
            {
                writer.WriteStartObject();
                writer.WriteNumber("ordinal", shape.Ordinal);
                writer.WriteString("section", shape.Section);
                writer.WriteNumber("rows", shape.RowCount);
                writer.WriteNumber("withheldValues", shape.WithheldValues);
                writer.WriteStartArray("columns");
                foreach (SemanticColumn column in shape.Columns)
                {
                    writer.WriteStartObject();
                    writer.WriteString("name", column.Name);
                    writer.WriteString("sqlType", column.SqlType);
                    writer.WriteBoolean("withheld", column.Withheld);
                    if (column.AllowsNull is { } allowsNull)
                    {
                        writer.WriteBoolean("allowsNull", allowsNull);
                    }
                    else
                    {
                        writer.WriteNull("allowsNull");
                    }

                    writer.WriteEndObject();
                }

                writer.WriteEndArray();
                writer.WriteEndObject();
            }

            writer.WriteEndArray();
        }

        public static void Revision(Utf8JsonWriter writer, SemanticRevision revision, int maxItems)
        {
            writer.WriteStartObject("revision");
            writer.WriteString("revisionDigest", revision.RevisionDigest);
            writer.WriteString("basis", revision.Basis);
            writer.WriteString("basisScope", "a mutable basis pointer; the dependency digests below establish the revision");
            writer.WriteString("readerDefinitionDigest", revision.ReaderDefinitionDigest);
            writer.WriteBoolean("pinned", revision.IsPinned);
            writer.WriteNumber("dependencies", revision.Dependencies.Length);
            writer.WriteNumber("unpinned", revision.Unpinned);
            writer.WriteNumber("omitted", Math.Max(0, revision.Dependencies.Length - maxItems));
            writer.WriteStartArray("items");
            foreach (SemanticDependency dependency in revision.Dependencies.Take(maxItems))
            {
                Dependency(writer, dependency);
            }

            writer.WriteEndArray();
            writer.WriteEndObject();
        }

        private static void Dependency(Utf8JsonWriter writer, SemanticDependency dependency)
        {
            writer.WriteStartObject();
            writer.WriteString("source", dependency.Source);
            writer.WriteString("kind", dependency.Kind);
            writer.WriteString("id", dependency.Id);
            writer.WriteString("locator", dependency.Locator);
            writer.WriteString("digest", dependency.Digest);
            writer.WriteEndObject();
        }

        public static void Coverage(Utf8JsonWriter writer, ImmutableArray<SemanticSection> sections, int expectedSections)
        {
            writer.WriteStartObject("coverage");
            writer.WriteNumber("expectedSections", expectedSections);
            writer.WriteNumber("presentSections", sections.Length);
            writer.WriteNumber("typedSections", sections.Count(section => section.Disposition == SemanticSectionDisposition.Typed));
            writer.WriteNumber("retainedSections", sections.Count(section => section.Disposition != SemanticSectionDisposition.Typed));
            writer.WriteString("statement", "Typed sections are interpreted by the contract; every other section and every non-entity row is retained verbatim and bound into the projection digest by source-text SHA-256.");
            writer.WriteStartArray("sections");
            foreach (SemanticSection section in sections)
            {
                writer.WriteStartObject();
                writer.WriteString("section", section.Name);
                writer.WriteNumber("ordinal", section.Ordinal);
                writer.WriteString("disposition", section.Disposition.ToString());
                writer.WriteNumber("rows", section.RowCount);
                writer.WriteBoolean("unordered", section.Unordered);
                if (section.Disposition == SemanticSectionDisposition.Typed && section.Raw == null)
                {
                    writer.WriteNumber("entities", section.EntityCount);
                    writer.WriteNumber("unprojected", section.UnprojectedCount);
                    writer.WriteStartObject("markers");
                    foreach (IGrouping<string?, SemanticSectionRow> marker in section.Rows.Where(row => row.Disposition == SemanticRowDisposition.Marker).GroupBy(row => row.Marker))
                    {
                        writer.WriteNumber(marker.Key ?? string.Empty, marker.Count());
                    }

                    writer.WriteEndObject();
                }

                writer.WriteEndObject();
            }

            writer.WriteEndArray();
            writer.WriteEndObject();
        }

        public static void Diagnostics(Utf8JsonWriter writer, ImmutableArray<SemanticDiagnostic> diagnostics, int maxItems)
        {
            writer.WriteStartObject("diagnostics");
            writer.WriteNumber("count", diagnostics.Length);
            writer.WriteNumber("errors", diagnostics.Count(diagnostic => diagnostic.Severity == SemanticSeverity.Error));
            writer.WriteNumber("warnings", diagnostics.Count(diagnostic => diagnostic.Severity == SemanticSeverity.Warning));
            writer.WriteNumber("omitted", Math.Max(0, diagnostics.Length - maxItems));
            writer.WriteStartArray("items");
            foreach (SemanticDiagnostic diagnostic in diagnostics.Take(maxItems))
            {
                writer.WriteStartObject();
                writer.WriteString("code", diagnostic.Code);
                writer.WriteString("severity", diagnostic.Severity.ToString());
                writer.WriteString("section", diagnostic.Section);
                if (diagnostic.Row is { } row)
                {
                    writer.WriteNumber("row", row);
                }
                else
                {
                    writer.WriteNull("row");
                }

                writer.WriteString("field", diagnostic.Field);
                writer.WriteString("message", diagnostic.Message);
                writer.WriteEndObject();
            }

            writer.WriteEndArray();
            writer.WriteEndObject();
        }
    }

    /// <summary>
    /// Semantic JSON equality: objects compare as property sets (objects with duplicate names as ordered member lists), arrays
    /// in order, strings by decoded value, numbers by exact source spelling.
    /// </summary>
    public static class SemanticJsonEquivalence
    {
        /// <summary>
        /// Returns true when both texts denote the same JSON value. On a difference, names the
        /// first differing path (property names and indexes only, never values).
        /// </summary>
        public static bool Equivalent(string left, string right, out string? difference)
        {
            using JsonDocument leftDocument = JsonDocument.Parse(left, new JsonDocumentOptions { MaxDepth = 256 });
            using JsonDocument rightDocument = JsonDocument.Parse(right, new JsonDocumentOptions { MaxDepth = 256 });
            return Compare(leftDocument.RootElement, rightDocument.RootElement, "$", out difference);
        }

        private static bool Compare(JsonElement left, JsonElement right, string path, out string? difference)
        {
            difference = null;
            if (left.ValueKind != right.ValueKind)
            {
                difference = path + ": value kind " + left.ValueKind + " versus " + right.ValueKind;
                return false;
            }

            switch (left.ValueKind)
            {
                case JsonValueKind.Object:
                    {
                        Dictionary<string, JsonElement>? leftMembers = Members(left);
                        Dictionary<string, JsonElement>? rightMembers = Members(right);
                        if (leftMembers == null || rightMembers == null)
                        {
                            // Duplicate names have no agreed meaning; such objects are equal only as identical ordered member lists.
                            return CompareOrdered(left, right, path, out difference);
                        }

                        foreach (string name in leftMembers.Keys.Union(rightMembers.Keys, StringComparer.Ordinal).OrderBy(name => name, StringComparer.Ordinal))
                        {
                            string memberPath = path + "." + name;
                            if (leftMembers.TryGetValue(name, out JsonElement leftValue) == false || rightMembers.TryGetValue(name, out JsonElement rightValue) == false)
                            {
                                difference = memberPath + ": present on one side only";
                                return false;
                            }

                            if (Compare(leftValue, rightValue, memberPath, out difference) == false)
                            {
                                return false;
                            }
                        }

                        return true;
                    }

                case JsonValueKind.Array:
                    {
                        int length = left.GetArrayLength();
                        if (length != right.GetArrayLength())
                        {
                            difference = path + ": array length " + length.ToString(CultureInfo.InvariantCulture) + " versus " + right.GetArrayLength().ToString(CultureInfo.InvariantCulture);
                            return false;
                        }

                        for (int index = 0; index < length; index++)
                        {
                            if (Compare(left[index], right[index], path + "[" + index.ToString(CultureInfo.InvariantCulture) + "]", out difference) == false)
                            {
                                return false;
                            }
                        }

                        return true;
                    }

                case JsonValueKind.String:
                    if (string.Equals(DecodeOrRaw(left), DecodeOrRaw(right), StringComparison.Ordinal))
                    {
                        return true;
                    }

                    difference = path + ": string value differs";
                    return false;

                case JsonValueKind.Number:
                    if (string.Equals(left.GetRawText(), right.GetRawText(), StringComparison.Ordinal))
                    {
                        return true;
                    }

                    difference = path + ": number spelling differs";
                    return false;

                default:
                    return true;
            }
        }

        private static bool CompareOrdered(JsonElement left, JsonElement right, string path, out string? difference)
        {
            difference = null;
            List<JsonProperty> leftMembers = left.EnumerateObject().ToList();
            List<JsonProperty> rightMembers = right.EnumerateObject().ToList();
            if (leftMembers.Count != rightMembers.Count)
            {
                difference = path + ": duplicate-property object member count differs";
                return false;
            }

            for (int index = 0; index < leftMembers.Count; index++)
            {
                if (string.Equals(leftMembers[index].Name, rightMembers[index].Name, StringComparison.Ordinal) == false)
                {
                    difference = path + ": duplicate-property object member order differs";
                    return false;
                }

                if (Compare(leftMembers[index].Value, rightMembers[index].Value, path + "." + leftMembers[index].Name, out difference) == false)
                {
                    return false;
                }
            }

            return true;
        }

        // A string that is not valid UTF-16 cannot be decoded; compare its exact spelling instead.
        private static string? DecodeOrRaw(JsonElement element)
        {
            try
            {
                return element.GetString();
            }
            catch (InvalidOperationException)
            {
                return "\u0000raw:" + element.GetRawText();
            }
        }

        private static Dictionary<string, JsonElement>? Members(JsonElement element)
        {
            var members = new Dictionary<string, JsonElement>(StringComparer.Ordinal);
            foreach (JsonProperty property in element.EnumerateObject())
            {
                if (members.TryAdd(property.Name, property.Value) == false)
                {
                    return null;
                }
            }

            return members;
        }
    }

    /// <summary>
    /// The <c>sql-json.v1</c> value encoding used to assemble multi-result-set readers into a
    /// named-section document. Lossless for the types it accepts: integers and SQL decimals keep their
    /// exact digits, strings are verbatim, date/times keep full precision, GUIDs use the "D" spelling and
    /// binary is base64. Nulls are written explicitly.
    /// </summary>
    public static class SemanticSqlValues
    {
        /// <summary>Identifies this encoding in receipts and contracts.</summary>
        public const string Encoding = "sql-json.v1";

        /// <summary>Writes one column value.</summary>
        public static void Write(Utf8JsonWriter writer, object? value)
        {
            switch (value)
            {
                case null:
                case DBNull:
                    writer.WriteNullValue();
                    break;
                case string text:
                    writer.WriteStringValue(text);
                    break;
                case bool flag:
                    writer.WriteBooleanValue(flag);
                    break;
                case byte number:
                    writer.WriteNumberValue(number);
                    break;
                case short number:
                    writer.WriteNumberValue(number);
                    break;
                case int number:
                    writer.WriteNumberValue(number);
                    break;
                case long number:
                    writer.WriteNumberValue(number);
                    break;
                case System.Data.SqlTypes.SqlDecimal number:
                    if (number.IsNull)
                    {
                        writer.WriteNullValue();
                    }
                    else
                    {
                        writer.WriteRawValue(number.ToString(), skipInputValidation: false);
                    }

                    break;
                case decimal number:
                    writer.WriteRawValue(number.ToString(CultureInfo.InvariantCulture), skipInputValidation: false);
                    break;
                case double number:
                    writer.WriteNumberValue(number);
                    break;
                case float number:
                    writer.WriteNumberValue(number);
                    break;
                case DateTime instant:
                    writer.WriteStringValue(instant.ToString("yyyy-MM-dd'T'HH:mm:ss.fffffff", CultureInfo.InvariantCulture));
                    break;
                case DateTimeOffset instant:
                    writer.WriteStringValue(instant.ToString("yyyy-MM-dd'T'HH:mm:ss.fffffffzzz", CultureInfo.InvariantCulture));
                    break;
                case TimeSpan span:
                    writer.WriteStringValue(span.ToString("c", CultureInfo.InvariantCulture));
                    break;
                case Guid guid:
                    writer.WriteStringValue(guid.ToString("D"));
                    break;
                case byte[] bytes:
                    writer.WriteBase64StringValue(bytes);
                    break;
                default:
                    throw new NotSupportedException("The sql-json.v1 encoding has no rule for " + value.GetType().FullName + ".");
            }
        }
    }
}
